patch:
diff --git a/calculator.js b/calculator.js
index c479731..0e55663 100644
--- a/calculator.js
+++ b/calculator.js
@@ -9 +9,8 @@ function multiply(a, b) {
-module.exports = { add, multiply };
+function divide(a, b) {
+  if (b === 0) {
+    throw new Error('Division by zero');
+  }
+  return a / b;
+}
+
+module.exports = { add, multiply, divide };
diff --git a/calculator.test.js b/calculator.test.js
index 657941c..64bd41e 100644
--- a/calculator.test.js
+++ b/calculator.test.js
@@ -3 +3 @@ const assert = require('node:assert');
-const { add, multiply } = require('./calculator');
+const { add, multiply, divide } = require('./calculator');
@@ -15,0 +16,10 @@ test('multiply multiplies two numbers', () => {
+
+test('divide divides two numbers', () => {
+  assert.strictEqual(divide(6, 2), 3);
+  assert.strictEqual(divide(-6, 2), -3);
+  assert.strictEqual(divide(0, 5), 0);
+});
+
+test('divide throws on division by zero', () => {
+  assert.throws(() => divide(5, 0), /Division by zero/);
+});
